{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dist_pairs = case['distances']
    dist = {}
    for u, v, d in dist_pairs:
        key = (u, v) if u < v else (v, u)
        dist[key] = d
    n = len(nodes)
    edges = []
    for i in range(n):
        u = nodes[i]
        for j in range(i+1, n):
            v = nodes[j]
            key = (u, v) if u < v else (v, u)
            d = dist.get(key)
            w = max(core[u], core[v], d)
            edges.append((u, v, w))
    edges.sort(key=lambda e: (e[2], e[0], e[1]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total += w
    return {"mst_edges": mst_edges, "total_weight": total}"}
